import java.util.*;
final class Canonical {
    record RankBond(int rank, int kind) implements Comparable<RankBond> {
        public int compareTo(RankBond other) {
            int c = Integer.compare(rank, other.rank);
            return c != 0 ? c : Integer.compare(kind, other.kind);
        }
    }
    record Neighborhood(int rank, List<RankBond> neighbors) implements Comparable<Neighborhood> {
        public int compareTo(Neighborhood other) {
            int c = Integer.compare(rank, other.rank);
            if (c != 0)
                return c;
            for (int i = 0; i < Math.min(neighbors.size(), other.neighbors.size()); i++) {
                c = neighbors.get(i).compareTo(other.neighbors.get(i));
                if (c != 0)
                    return c;
            }
            return Integer.compare(neighbors.size(), other.neighbors.size());
        }
    }
    record Ranks(int[] values, int classes) {}
    record Result(String smiles, int classes) {}
    record Child(int atom, Molecule.Bond bond) {}
    static <T> int[] dense(List<T> values, Comparator<T> comparator) {
        Map<T, Integer> ranks = new TreeMap<>(comparator);
        for (T value : values)
            ranks.put(value, 0);
        int rank = 1;
        for (T key : ranks.keySet())
            ranks.put(key, rank++);
        int[] result = new int[values.size()];
        for (int i = 0; i < result.length; i++)
            result[i] = ranks.get(values.get(i));
        return result;
    }
    static int distinct(int[] values) {
        Set<Integer> unique = new HashSet<>();
        for (int value : values)
            unique.add(value);
        return unique.size();
    }
    static int[] refine(Molecule molecule, int[] input) {
        int[] ranks = input;
        while (true) {
            List<Neighborhood> values = new ArrayList<>();
            for (int atom = 0; atom < molecule.atoms.size(); atom++) {
                List<RankBond> neighbors = new ArrayList<>();
                for (var entry : molecule.neighbors.get(atom).entrySet())
                    neighbors.add(new RankBond(ranks[entry.getKey()], entry.getValue().kind));
                neighbors.sort(RankBond::compareTo);
                values.add(new Neighborhood(ranks[atom], neighbors));
            }
            int[] next = dense(values, Neighborhood::compareTo);
            if (distinct(next) == distinct(ranks))
                return next;
            ranks = next;
        }
    }
    static Ranks ranks(Molecule molecule) {
        List<List<Integer>> invariants = new ArrayList<>();
        for (int number = 0; number < molecule.atoms.size(); number++) {
            Molecule.Atom atom = molecule.atoms.get(number);
            invariants.add(List.of(molecule.degree(number), atom.element.number(), atom.mass,
                                   atom.charge, atom.hydrogens, atom.aromatic ? 1 : 0));
        }
        int[] ranks = refine(molecule, dense(invariants, RingsAromatic::compareSequence));
        int classes = distinct(ranks);
        while (distinct(ranks) != ranks.length) {
            Map<Integer, Integer> counts = new TreeMap<>();
            for (int rank : ranks)
                counts.merge(rank, 1, Integer::sum);
            int tied = 0;
            for (var entry : counts.entrySet())
                if (entry.getValue() > 1) {
                    tied = entry.getKey();
                    break;
                }
            int first = 0;
            while (ranks[first] != tied)
                first++;
            List<Integer> values = new ArrayList<>();
            for (int i = 0; i < ranks.length; i++)
                values.add(2 * ranks[i] - (i == first ? 1 : 0));
            ranks = refine(molecule, dense(values, Integer::compare));
        }
        return new Ranks(ranks, classes);
    }
    static String atomNotation(Molecule molecule, int number) {
        Molecule.Atom atom = molecule.atoms.get(number);
        String symbol = atom.element.symbol();
        boolean ordinary = Molecule.ORGANIC.contains(symbol) &&
                           (!atom.aromatic || Molecule.AROMATIC.contains(symbol)) &&
                           atom.mass == 0 && atom.charge == 0;
        if (atom.aromatic) {
            ordinary =
                ordinary && molecule.needsPi(number, atom.hydrogens) == molecule.needsPi(number, 0);
            symbol = symbol.toLowerCase(Locale.ROOT);
        }
        Integer hydrogens = Molecule.organicHydrogens(atom, molecule.bondTotal(number));
        if (ordinary && hydrogens != null && hydrogens == atom.hydrogens)
            return symbol;
        StringBuilder text = new StringBuilder("[");
        if (atom.mass != 0)
            text.append(atom.mass);
        text.append(symbol);
        if (atom.hydrogens > 0) {
            text.append('H');
            if (atom.hydrogens != 1)
                text.append(atom.hydrogens);
        }
        if (atom.charge != 0) {
            text.append(atom.charge > 0 ? '+' : '-');
            if (Math.abs(atom.charge) != 1)
                text.append(Math.abs(atom.charge));
        }
        return text.append(']').toString();
    }
    static String bondSymbol(Molecule molecule, Molecule.Bond bond) {
        boolean inRing = bond.ring && molecule.atoms.get(bond.ends.first()).aromatic &&
                         molecule.atoms.get(bond.ends.second()).aromatic;
        return switch (bond.kind) {
            case 1 -> inRing ? "-" : "";
            case 2 -> "=";
            case 3 -> "#";
            default -> inRing ? "" : ":";
        };
    }
    static final class Writer {
        Molecule molecule;
        int[] ranks, visits;
        int visited;
        List<List<Child>> children = new ArrayList<>();
        Set<Molecule.Edge> closures = new HashSet<>();
        Map<Molecule.Edge, Integer> assignments = new HashMap<>();
        Set<Integer> occupied = new HashSet<>();
        Writer(Molecule molecule, int[] ranks) {
            this.molecule = molecule;
            this.ranks = ranks;
            visits = new int[ranks.length];
            for (int rank : ranks)
                children.add(new ArrayList<>());
        }
        void visit(int atom, Molecule.Bond incoming) {
            visits[atom] = ++visited;
            List<Integer> neighbors = new ArrayList<>(molecule.neighbors.get(atom).keySet());
            neighbors.sort(Comparator.comparingInt(n -> ranks[n]));
            for (int neighbor : neighbors) {
                Molecule.Bond bond = molecule.neighbors.get(atom).get(neighbor);
                if (bond == incoming || closures.contains(bond.ends))
                    continue;
                if (visits[neighbor] == 0) {
                    children.get(atom).add(new Child(neighbor, bond));
                    visit(neighbor, bond);
                } else
                    closures.add(bond.ends);
            }
        }
        String write(int atom) {
            StringBuilder text = new StringBuilder(atomNotation(molecule, atom));
            List<Integer> neighbors = new ArrayList<>(molecule.neighbors.get(atom).keySet());
            neighbors.sort(Comparator.comparingInt(n -> visits[n]));
            for (int neighbor : neighbors) {
                Molecule.Bond bond = molecule.neighbors.get(atom).get(neighbor);
                if (!closures.contains(bond.ends))
                    continue;
                Integer assigned = assignments.remove(bond.ends);
                int number;
                String symbol;
                if (assigned != null) {
                    number = assigned;
                    occupied.remove(number);
                    symbol = "";
                } else {
                    number = 1;
                    while (occupied.contains(number))
                        number++;
                    assignments.put(bond.ends, number);
                    occupied.add(number);
                    symbol = bondSymbol(molecule, bond);
                }
                text.append(symbol).append(number < 10
                                               ? Integer.toString(number)
                                               : String.format(Locale.ROOT, "%%%02d", number));
            }
            List<Child> descendants = children.get(atom);
            for (int i = 0; i < descendants.size(); i++) {
                Child child = descendants.get(i);
                String continuation = bondSymbol(molecule, child.bond()) + write(child.atom());
                if (i + 1 < descendants.size())
                    text.append('(').append(continuation).append(')');
                else
                    text.append(continuation);
            }
            return text.toString();
        }
    }
    static Result canonicalize(Molecule molecule) {
        Ranks ranks = ranks(molecule);
        Writer writer = new Writer(molecule, ranks.values());
        int root = 0;
        while (ranks.values()[root] != 1)
            root++;
        writer.visit(root, null);
        return new Result(writer.write(root), ranks.classes());
    }
}

import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
public final class Main {
    static final List<String> QUERY_KINDS = List.of("MATCH", "CONTAINS", "MATRIX", "NEAREST",
                                                    "WITHIN", "COMPARE", "CLUSTER"),
                              SYSTEM_KINDS = List.of("isolated", "fused", "spiro", "bridged");
    record Line(int number, String text) {}
    record Fraction(int numerator, int denominator) implements Comparable<Fraction> {
        Fraction {
            int a = numerator, b = denominator;
            while (b != 0) {
                int r = a % b;
                a = b;
                b = r;
            }
            numerator /= a;
            denominator /= a;
        }
        public int compareTo(Fraction other) {
            return Integer.compare(numerator * other.denominator, other.numerator * denominator);
        }
        public String toString() { return numerator + "/" + denominator; }
    }
    record Properties(String formula, int weight, int heavy, int rotatable, int donors,
                      int acceptors, String lipinski, int charge) {}
    record RingSystem(List<Integer> rings, int atoms, String kind) {}
    static final class Prepared {
        Molecule molecule;
        Properties properties;
        String canonical, scaffold;
        int classes, paths;
        BitSet bits;
        List<RingSystem> systems;
        List<Boolean> aromaticRings;
        Prepared(Molecule molecule) {
            this.molecule = molecule;
            properties = molecularProperties(molecule);
            Canonical.Result result = Canonical.canonicalize(molecule);
            canonical = result.smiles();
            classes = result.classes();
            Molecule scaffoldMolecule = scaffoldMolecule(molecule);
            scaffold =
                scaffoldMolecule == null ? null : Canonical.canonicalize(scaffoldMolecule).smiles();
            systems = ringSystems(molecule);
            aromaticRings = new ArrayList<>();
            for (List<Integer> ring : molecule.rings) {
                boolean aromatic = true;
                for (int atom : ring)
                    if (!molecule.atoms.get(atom).aromatic)
                        aromatic = false;
                aromaticRings.add(aromatic);
            }
            Search.Fingerprint fingerprint = Search.fingerprint(molecule);
            bits = fingerprint.bits();
            paths = fingerprint.paths();
        }
        String name() { return molecule.name; }
    }
    static final class Query {
        String kind, id;
        List<String> arguments;
        Molecule pattern;
        Fraction threshold;
        int count;
        Query(String kind, String id, List<String> arguments) {
            this.kind = kind;
            this.id = id;
            this.arguments = arguments;
        }
    }
    record ReadMolecules(List<Prepared> molecules, List<String> errors) {}
    record ReadQueries(List<Query> queries, List<String> errors) {}
    record Hit(Prepared molecule, Search.Embeddings embeddings) {}
    record Neighbor(Prepared molecule, Search.Similarity value) {}
    static List<Line> dataLines(String file) throws Exception {
        List<Line> result = new ArrayList<>();
        List<String> lines = Files.readAllLines(Path.of("input", file), StandardCharsets.US_ASCII);
        for (int i = 0; i < lines.size(); i++) {
            String line = lines.get(i);
            if (!line.isEmpty() && !line.startsWith("#"))
                result.add(new Line(i + 1, line));
        }
        return result;
    }
    static boolean validName(String value) {
        if (value.isEmpty() || value.length() > 32)
            return false;
        for (char c : value.toCharArray())
            if (!(c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c >= '0' && c <= '9' ||
                  c == '_' || c == '-'))
                return false;
        return true;
    }
    static boolean validNumber(String value, int minimum, int maximum) {
        if (value.isEmpty() || value.length() > 2 || value.length() > 1 && value.charAt(0) == '0')
            return false;
        for (char c : value.toCharArray())
            if (c < '0' || c > '9')
                return false;
        int number = Integer.parseInt(value);
        return minimum <= number && number <= maximum;
    }
    static Fraction threshold(String value) {
        String[] parts = value.split("/", -1);
        if (parts.length != 2 || !validNumber(parts[0], 0, 99) || !validNumber(parts[1], 1, 99))
            return null;
        int p = Integer.parseInt(parts[0]), q = Integer.parseInt(parts[1]);
        return p <= q ? new Fraction(p, q) : null;
    }
    static String atomNumbers(Collection<Integer> atoms, String separator) {
        List<String> numbers = new ArrayList<>();
        for (int atom : atoms)
            numbers.add(Integer.toString(atom + 1));
        return String.join(separator, numbers);
    }
    static String memberNames(List<Prepared> molecules) {
        return String.join(",", molecules.stream().map(Prepared::name).toList());
    }
    static void cause(Map<String, Integer> causes, String reason) {
        causes.merge(reason, 1, Integer::sum);
    }
    static void analyze(Molecule molecule) {
        RingsAromatic.findRings(molecule);
        for (Molecule.Bond bond : molecule.bonds.values())
            bond.kind = bond.symbol != null ? Molecule.bondType(bond.symbol)
                        : molecule.atoms.get(bond.ends.first()).aromatic &&
                                molecule.atoms.get(bond.ends.second()).aromatic && bond.ring
                            ? 4
                            : 1;
        Set<Integer> needing = new TreeSet<>();
        for (int number = 0; number < molecule.atoms.size(); number++)
            if (molecule.needsPi(number, molecule.atoms.get(number).hydrogens))
                needing.add(number);
        RingsAromatic.kekulize(molecule, needing);
        for (int number = 0; number < molecule.atoms.size(); number++) {
            Molecule.Atom atom = molecule.atoms.get(number);
            int total = molecule.bondTotal(number);
            if (atom.bracket) {
                if (total + atom.hydrogens >
                    atom.element.valences().getLast() + Math.abs(atom.charge))
                    throw new Molecule.AnalysisError("bad valence", atom.column);
            } else {
                Integer hydrogens = Molecule.organicHydrogens(atom, total);
                if (hydrogens == null)
                    throw new Molecule.AnalysisError("bad valence", atom.column);
                atom.hydrogens = hydrogens;
            }
        }
    }
    static Properties molecularProperties(Molecule molecule) {
        Map<String, Integer> counts = new TreeMap<>();
        int hydrogens = 0, weight = 0, heavy = 0, charge = 0;
        for (Molecule.Atom atom : molecule.atoms) {
            counts.merge(atom.element.symbol(), 1, Integer::sum);
            hydrogens += atom.hydrogens;
            weight += atom.mass != 0 ? atom.mass * 1000 : atom.element.weight();
            if (!atom.element.symbol().equals("H"))
                heavy++;
            charge += atom.charge;
        }
        counts.merge("H", hydrogens, Integer::sum);
        List<String> symbols = new ArrayList<>();
        for (var entry : counts.entrySet())
            if (entry.getValue() > 0)
                symbols.add(entry.getKey());
        if (counts.getOrDefault("C", 0) > 0) {
            symbols.remove("C");
            List<String> first = new ArrayList<>();
            first.add("C");
            if (symbols.remove("H"))
                first.add("H");
            first.addAll(symbols);
            symbols = first;
        }
        StringBuilder formula = new StringBuilder();
        for (String symbol : symbols) {
            formula.append(symbol);
            if (counts.get(symbol) != 1)
                formula.append(counts.get(symbol));
        }
        weight += hydrogens * molecule.elements.get("H").weight();
        int[] heavyDegrees = new int[molecule.atoms.size()];
        for (int atom = 0; atom < heavyDegrees.length; atom++)
            for (int neighbor : molecule.neighbors.get(atom).keySet())
                if (!molecule.atoms.get(neighbor).element.symbol().equals("H"))
                    heavyDegrees[atom]++;
        Set<Integer> tripleEnds = new HashSet<>();
        for (Molecule.Bond bond : molecule.bonds.values())
            if (bond.multiplicity == 3) {
                tripleEnds.add(bond.ends.first());
                tripleEnds.add(bond.ends.second());
            }
        int rotatable = 0;
        for (Molecule.Bond bond : molecule.bonds.values())
            if (bond.multiplicity == 1 && !bond.ring && heavyDegrees[bond.ends.first()] >= 2 &&
                heavyDegrees[bond.ends.second()] >= 2 && !tripleEnds.contains(bond.ends.first()) &&
                !tripleEnds.contains(bond.ends.second()))
                rotatable++;
        int donors = 0, acceptors = 0;
        for (int number = 0; number < molecule.atoms.size(); number++) {
            Molecule.Atom atom = molecule.atoms.get(number);
            if (atom.element.symbol().equals("N") || atom.element.symbol().equals("O")) {
                acceptors++;
                int attached = atom.hydrogens;
                for (int neighbor : molecule.neighbors.get(number).keySet())
                    if (molecule.atoms.get(neighbor).element.symbol().equals("H"))
                        attached++;
                if (attached >= 1)
                    donors++;
            }
        }
        int violations =
            (weight > 500000 ? 1 : 0) + (donors > 5 ? 1 : 0) + (acceptors > 10 ? 1 : 0);
        return new Properties(formula.toString(), weight, heavy, rotatable, donors, acceptors,
                              violations <= 1 ? "pass" : "fail", charge);
    }
    static Molecule scaffoldMolecule(Molecule molecule) {
        if (molecule.rings.isEmpty())
            return null;
        Set<Integer> remaining = new TreeSet<>();
        for (int i = 0; i < molecule.atoms.size(); i++)
            remaining.add(i);
        while (true) {
            Integer leaf = null;
            for (int atom : remaining) {
                if (molecule.ringAtoms.contains(atom))
                    continue;
                int degree = 0;
                for (int neighbor : molecule.neighbors.get(atom).keySet())
                    if (remaining.contains(neighbor))
                        degree++;
                if (degree == 1) {
                    leaf = atom;
                    break;
                }
            }
            if (leaf == null)
                break;
            remaining.remove(leaf);
        }
        Set<Integer> kept = new TreeSet<>(remaining);
        for (int atom : remaining)
            for (var entry : molecule.neighbors.get(atom).entrySet())
                if (!remaining.contains(entry.getKey()) && entry.getValue().kind == 2)
                    kept.add(entry.getKey());
        Molecule scaffold = new Molecule(molecule.elements);
        Map<Integer, Integer> renumber = new HashMap<>();
        for (int number : kept) {
            Molecule.Atom original = molecule.atoms.get(number);
            int added = 0;
            for (var entry : molecule.neighbors.get(number).entrySet())
                if (!kept.contains(entry.getKey()))
                    added += entry.getValue().multiplicity;
            Molecule.Atom atom = new Molecule.Atom(
                original.element, original.aromatic, original.mass, original.charge,
                original.hydrogens + added, original.bracket, original.column);
            renumber.put(number, scaffold.addAtom(atom));
        }
        for (Molecule.Bond original : molecule.bonds.values()) {
            int first = original.ends.first(), second = original.ends.second();
            if (kept.contains(first) && kept.contains(second)) {
                Molecule.Bond bond =
                    scaffold.addBond(renumber.get(first), renumber.get(second), original.symbol);
                bond.kind = original.kind;
                bond.multiplicity = original.multiplicity;
                bond.ring = original.ring;
            }
        }
        for (List<Integer> ring : molecule.rings) {
            List<Integer> transformed = new ArrayList<>();
            for (int atom : ring)
                transformed.add(renumber.get(atom));
            scaffold.rings.add(transformed);
        }
        for (int atom : molecule.ringAtoms)
            scaffold.ringAtoms.add(renumber.get(atom));
        return scaffold;
    }
    static List<RingSystem> ringSystems(Molecule molecule) {
        List<Set<Integer>> atomSets = new ArrayList<>();
        List<Set<Integer>> connections = new ArrayList<>();
        for (List<Integer> ring : molecule.rings) {
            atomSets.add(new HashSet<>(ring));
            connections.add(new TreeSet<>());
        }
        Map<Molecule.Edge, String> relations = new HashMap<>();
        for (int first = 0; first < atomSets.size(); first++)
            for (int second = first + 1; second < atomSets.size(); second++) {
                Set<Integer> shared = new TreeSet<>(atomSets.get(first));
                shared.retainAll(atomSets.get(second));
                if (shared.isEmpty())
                    continue;
                connections.get(first).add(second);
                connections.get(second).add(first);
                String relation;
                if (shared.size() == 1)
                    relation = "spiro";
                else if (shared.size() == 2) {
                    List<Integer> pair = new ArrayList<>(shared);
                    relation = molecule.neighbors.get(pair.getFirst()).containsKey(pair.get(1))
                                   ? "fused"
                                   : "bridged";
                } else
                    relation = "bridged";
                relations.put(new Molecule.Edge(first, second), relation);
            }
        List<RingSystem> systems = new ArrayList<>();
        Set<Integer> unseen = new TreeSet<>();
        for (int i = 0; i < atomSets.size(); i++)
            unseen.add(i);
        while (!unseen.isEmpty()) {
            int start = Collections.min(unseen);
            unseen.remove(start);
            Set<Integer> component = new TreeSet<>();
            component.add(start);
            Deque<Integer> queue = new ArrayDeque<>();
            queue.add(start);
            while (!queue.isEmpty())
                for (int neighbor : connections.get(queue.remove()))
                    if (unseen.remove(neighbor)) {
                        component.add(neighbor);
                        queue.add(neighbor);
                    }
            Set<String> kinds = new HashSet<>();
            for (var entry : relations.entrySet())
                if (component.contains(entry.getKey().first()) &&
                    component.contains(entry.getKey().second()))
                    kinds.add(entry.getValue());
            String kind = component.size() == 1       ? "isolated"
                          : kinds.contains("bridged") ? "bridged"
                          : kinds.contains("fused")   ? "fused"
                                                      : "spiro";
            Set<Integer> atoms = new HashSet<>();
            for (int ring : component)
                atoms.addAll(atomSets.get(ring));
            systems.add(new RingSystem(new ArrayList<>(component), atoms.size(), kind));
        }
        return systems;
    }
    static ReadMolecules readMolecules(Map<String, Molecule.Element> elements,
                                       Map<String, Integer> causes) throws Exception {
        List<Prepared> molecules = new ArrayList<>();
        List<String> errors = new ArrayList<>();
        Set<String> reserved = new HashSet<>();
        List<Line> lines = dataLines("molecules.smi");
        for (Line line : lines) {
            String[] tokens = line.text().split(" ", -1);
            if (tokens.length != 2 || tokens[0].isEmpty() || !validName(tokens[1])) {
                errors.add("line " + line.number() + ": bad line");
                cause(causes, "bad line");
                continue;
            }
            String name = tokens[1];
            if (!reserved.add(name)) {
                errors.add("line " + line.number() + " " + name + ": duplicate name");
                cause(causes, "duplicate name");
                continue;
            }
            Molecule molecule;
            try {
                molecule = SmilesParser.parse(tokens[0], elements, false);
                analyze(molecule);
            } catch (Molecule.AnalysisError error) {
                errors.add("line " + line.number() + " " + name + ": " + error.reason +
                           " at column " + error.column);
                cause(causes, error.reason);
                continue;
            }
            molecule.name = name;
            molecule.order = molecules.size();
            molecules.add(new Prepared(molecule));
        }
        List<String> paragraph = new ArrayList<>();
        paragraph.add("MOLECULES lines=" + lines.size() + " valid=" + molecules.size() +
                      " errors=" + errors.size());
        paragraph.addAll(errors);
        return new ReadMolecules(molecules, paragraph);
    }
    static String checkArguments(Query query, Map<String, Molecule.Element> elements,
                                 Map<String, Prepared> byName) {
        List<String> arguments = query.arguments;
        int minimum = query.kind.equals("MATRIX")                                  ? 2
                      : query.kind.equals("MATCH") || query.kind.equals("CLUSTER") ? 1
                                                                                   : 2,
            maximum = query.kind.equals("MATRIX") ? 12 : minimum;
        if (arguments.size() < minimum || arguments.size() > maximum)
            return "bad arguments";
        if (query.kind.equals("MATCH")) {
            try {
                query.pattern = SmilesParser.parse(arguments.getFirst(), elements, true);
            } catch (Molecule.AnalysisError error) {
                return "bad pattern " + error.reason + " at column " + error.column;
            }
        } else if (query.kind.equals("CLUSTER")) {
            query.threshold = threshold(arguments.getFirst());
            if (query.threshold == null)
                return "bad threshold";
        } else if (Set.of("CONTAINS", "MATRIX", "COMPARE").contains(query.kind)) {
            for (String name : arguments)
                if (!byName.containsKey(name))
                    return "unknown molecule " + name;
            if (new HashSet<>(arguments).size() != arguments.size())
                return "repeated molecule";
        } else {
            if (!byName.containsKey(arguments.getFirst()))
                return "unknown molecule " + arguments.getFirst();
            if (query.kind.equals("NEAREST")) {
                if (!validNumber(arguments.get(1), 1, 99))
                    return "bad count";
                query.count = Integer.parseInt(arguments.get(1));
            } else {
                query.threshold = threshold(arguments.get(1));
                if (query.threshold == null)
                    return "bad threshold";
            }
        }
        return null;
    }
    static ReadQueries readQueries(Map<String, Molecule.Element> elements,
                                   Map<String, Prepared> byName, Map<String, Integer> causes)
        throws Exception {
        List<Query> queries = new ArrayList<>();
        List<String> errors = new ArrayList<>();
        Set<String> reserved = new HashSet<>();
        List<Line> lines = dataLines("queries.txt");
        for (Line line : lines) {
            String[] tokens = line.text().split(" ", -1);
            String kind = tokens[0], id = tokens.length >= 2 ? tokens[1] : null, reason;
            if (!QUERY_KINDS.contains(kind))
                reason = "unknown query";
            else if (id == null || !validName(id))
                reason = "bad id";
            else if (!reserved.add(id))
                reason = "duplicate id";
            else {
                Query query = new Query(
                    kind, id, List.copyOf(Arrays.asList(tokens).subList(2, tokens.length)));
                reason = checkArguments(query, elements, byName);
                if (reason == null) {
                    queries.add(query);
                    continue;
                }
            }
            String text;
            if (reason.equals("unknown query"))
                text = "line " + line.number() + ": unknown query";
            else if (reason.equals("bad id"))
                text = "line " + line.number() + " " + kind + ": bad id";
            else
                text = "line " + line.number() + " " + kind + " " + id + ": " + reason;
            errors.add(text);
            cause(causes, reason.startsWith("bad pattern ")        ? "bad pattern"
                          : reason.startsWith("unknown molecule ") ? "unknown molecule"
                                                                   : reason);
        }
        List<String> paragraph = new ArrayList<>();
        paragraph.add("QUERIES lines=" + lines.size() + " valid=" + queries.size() +
                      " errors=" + errors.size());
        paragraph.addAll(errors);
        return new ReadQueries(queries, paragraph);
    }
    static List<String> propertiesLines(List<Prepared> molecules) {
        List<String> lines = new ArrayList<>();
        lines.add("name,formula,weight,heavy_atoms,rings,rotatable,donors,acceptors,lipinski");
        for (Prepared prepared : molecules) {
            Properties p = prepared.properties;
            int weight = p.weight();
            lines.add(prepared.name() + "," + p.formula() + "," + weight / 1000 + "." +
                      String.format(Locale.ROOT, "%03d", weight % 1000) + "," + p.heavy() + "," +
                      prepared.molecule.rings.size() + "," + p.rotatable() + "," + p.donors() +
                      "," + p.acceptors() + "," + p.lipinski());
        }
        return lines;
    }
    static List<List<String>> canonicalParagraphs(List<Prepared> molecules) {
        Map<String, List<Prepared>> byCanonical = new LinkedHashMap<>(),
                                    byFormula = new LinkedHashMap<>(),
                                    byScaffold = new LinkedHashMap<>();
        int acyclic = 0;
        for (Prepared molecule : molecules) {
            byCanonical.computeIfAbsent(molecule.canonical, k -> new ArrayList<>()).add(molecule);
            byFormula.computeIfAbsent(molecule.properties.formula(), k -> new ArrayList<>())
                .add(molecule);
            if (molecule.scaffold == null)
                acyclic++;
            else
                byScaffold.computeIfAbsent(molecule.scaffold, k -> new ArrayList<>()).add(molecule);
        }
        List<String> canonical = new ArrayList<>();
        canonical.add("CANONICAL molecules=" + molecules.size() + " unique=" + byCanonical.size());
        for (Prepared molecule : molecules) {
            int charge = molecule.properties.charge();
            canonical.add(molecule.name() + " " + molecule.canonical + " classes=" +
                          molecule.classes + " charge=" + (charge > 0 ? "+" : "") + charge);
        }
        List<Map.Entry<String, List<Prepared>>> duplicates = new ArrayList<>();
        int count = 0;
        for (var entry : byCanonical.entrySet())
            if (entry.getValue().size() >= 2) {
                duplicates.add(entry);
                count += entry.getValue().size();
            }
        List<String> duplicateLines = new ArrayList<>();
        duplicateLines.add("DUPLICATES groups=" + duplicates.size() + " molecules=" + count);
        for (int i = 0; i < duplicates.size(); i++) {
            var entry = duplicates.get(i);
            duplicateLines.add("group " + (i + 1) + " " + entry.getKey() +
                               " members=" + memberNames(entry.getValue()));
        }
        List<String> isomerRecords = new ArrayList<>();
        for (var entry : byFormula.entrySet()) {
            Set<String> forms = new HashSet<>();
            for (Prepared molecule : entry.getValue())
                forms.add(molecule.canonical);
            if (forms.size() >= 2)
                isomerRecords.add("isomer " + (isomerRecords.size() + 1) + " " + entry.getKey() +
                                  " forms=" + forms.size() +
                                  " members=" + memberNames(entry.getValue()));
        }
        List<String> isomers = new ArrayList<>();
        isomers.add("ISOMERS groups=" + isomerRecords.size());
        isomers.addAll(isomerRecords);
        List<String> scaffolds = new ArrayList<>();
        scaffolds.add("SCAFFOLDS distinct=" + byScaffold.size() + " acyclic=" + acyclic);
        List<Map.Entry<String, List<Prepared>>> ordered = new ArrayList<>(byScaffold.entrySet());
        ordered.sort(Comparator
                         .comparingInt(
                             (Map.Entry<String, List<Prepared>> entry) -> - entry.getValue().size())
                         .thenComparing(Map.Entry::getKey));
        for (int i = 0; i < ordered.size(); i++) {
            var entry = ordered.get(i);
            scaffolds.add("scaffold " + (i + 1) + " " + entry.getKey() + " count=" +
                          entry.getValue().size() + " members=" + memberNames(entry.getValue()));
        }
        return List.of(canonical, duplicateLines, isomers, scaffolds);
    }
    static List<List<String>> ringParagraphs(List<Prepared> molecules) {
        List<List<String>> paragraphs = new ArrayList<>();
        Map<Integer, Integer> sizes = new TreeMap<>();
        Map<String, Integer> kinds = new HashMap<>();
        int totalAromatic = 0, totalRings = 0;
        for (Prepared prepared : molecules) {
            Molecule molecule = prepared.molecule;
            if (molecule.rings.isEmpty())
                continue;
            int aromatic = 0, ringBonds = 0;
            for (boolean value : prepared.aromaticRings)
                if (value)
                    aromatic++;
            totalAromatic += aromatic;
            totalRings += molecule.rings.size();
            for (Molecule.Bond bond : molecule.bonds.values())
                if (bond.ring)
                    ringBonds++;
            List<String> paragraph = new ArrayList<>();
            paragraph.add("MOLECULE " + molecule.name + " atoms=" + molecule.atoms.size() +
                          " bonds=" + molecule.bonds.size() + " rings=" + molecule.rings.size() +
                          " aromatic=" + aromatic + " systems=" + prepared.systems.size() +
                          " ring_atoms=" + molecule.ringAtoms.size() + " ring_bonds=" + ringBonds);
            for (int i = 0; i < molecule.rings.size(); i++) {
                List<Integer> ring = molecule.rings.get(i);
                int hetero = 0;
                for (int atom : ring)
                    if (!molecule.atoms.get(atom).element.symbol().equals("C"))
                        hetero++;
                paragraph.add("ring " + (i + 1) + " size=" + ring.size() +
                              " aromatic=" + (prepared.aromaticRings.get(i) ? "yes" : "no") +
                              " hetero=" + hetero + " atoms=" + atomNumbers(ring, "-"));
                sizes.merge(ring.size(), 1, Integer::sum);
            }
            for (int i = 0; i < prepared.systems.size(); i++) {
                RingSystem system = prepared.systems.get(i);
                kinds.merge(system.kind(), 1, Integer::sum);
                paragraph.add("system " + (i + 1) + " kind=" + system.kind() + " rings=" +
                              atomNumbers(system.rings(), ",") + " atoms=" + system.atoms());
            }
            List<String> doubleBonds = new ArrayList<>();
            for (Molecule.Bond bond : molecule.bonds.values())
                if (bond.kind == 4 && bond.multiplicity == 2)
                    doubleBonds.add((bond.ends.first() + 1) + "=" + (bond.ends.second() + 1));
            paragraph.add("kekule " +
                          (doubleBonds.isEmpty() ? "-" : String.join(" ", doubleBonds)));
            paragraphs.add(paragraph);
        }
        List<String> summary = new ArrayList<>();
        summary.add("SUMMARY molecules=" + molecules.size() + " cyclic=" + paragraphs.size() +
                    " rings=" + totalRings + " aromatic=" + totalAromatic);
        List<String> sizeValues = new ArrayList<>();
        for (var entry : sizes.entrySet())
            sizeValues.add(entry.getKey() + "=" + entry.getValue());
        summary.add("sizes " + (sizeValues.isEmpty() ? "-" : String.join(" ", sizeValues)));
        List<String> systemValues = new ArrayList<>();
        for (String kind : SYSTEM_KINDS)
            systemValues.add(kind + "=" + kinds.getOrDefault(kind, 0));
        summary.add("systems " + String.join(" ", systemValues));
        paragraphs.add(summary);
        return paragraphs;
    }
    static List<List<String>> substructureParagraphs(List<Query> queries, List<Prepared> molecules,
                                                     Map<String, Prepared> byName) {
        List<List<String>> paragraphs = new ArrayList<>();
        int patterns = 0, hits = 0, contains = 0, found = 0;
        for (Query query : queries)
            if (query.kind.equals("MATCH")) {
                patterns++;
                List<Hit> matches = new ArrayList<>();
                int total = 0;
                for (Prepared molecule : molecules) {
                    Search.Embeddings embeddings =
                        Search.embeddings(query.pattern, molecule.molecule);
                    if (embeddings.count() > 0) {
                        matches.add(new Hit(molecule, embeddings));
                        total += embeddings.count();
                    }
                }
                hits += matches.size();
                List<String> paragraph = new ArrayList<>();
                paragraph.add("MATCH " + query.id + " " + query.arguments.getFirst() + " atoms=" +
                              query.pattern.atoms.size() + " bonds=" + query.pattern.bonds.size() +
                              " hits=" + matches.size() + " embeddings=" + total);
                Hit top = null;
                for (Hit hit : matches) {
                    Search.Embeddings e = hit.embeddings();
                    paragraph.add(hit.molecule().name() + " count=" + e.count() + " unique=" +
                                  e.unique() + " map=" + atomNumbers(e.mapping(), ","));
                    if (top == null || e.count() > top.embeddings().count())
                        top = hit;
                }
                if (top != null)
                    paragraph.add("top " + top.molecule().name() +
                                  " count=" + top.embeddings().count());
                paragraphs.add(paragraph);
            } else if (query.kind.equals("CONTAINS")) {
                contains++;
                Prepared first = byName.get(query.arguments.getFirst()),
                         second = byName.get(query.arguments.get(1));
                Search.Embeddings e =
                    Search.embeddings(Search.moleculePattern(first.molecule), second.molecule);
                String text =
                    "CONTAINS " + query.id + " " + first.name() + " " + second.name() + " result=";
                if (e.count() > 0) {
                    found++;
                    text += "yes count=" + e.count() + " unique=" + e.unique() +
                            " map=" + atomNumbers(e.mapping(), ",");
                } else
                    text += "no";
                paragraphs.add(List.of(text));
            }
        paragraphs.add(List.of("SUMMARY patterns=" + patterns + " hits=" + hits +
                               " contains=" + contains + " found=" + found));
        return paragraphs;
    }
    static Fraction ratio(Search.Similarity value) {
        return new Fraction(value.common(), value.union());
    }
    static final class Similarities {
        Map<Molecule.Edge, Search.Similarity> cache = new HashMap<>();
        Search.Similarity get(Prepared first, Prepared second) {
            Molecule.Edge key = new Molecule.Edge(first.molecule.order, second.molecule.order);
            return cache.computeIfAbsent(key, k -> Search.tanimoto(first.bits, second.bits));
        }
    }
    static List<String> matrixParagraph(Query query, Map<String, Prepared> byName,
                                        Similarities similarities) {
        List<Prepared> molecules = new ArrayList<>();
        for (String name : query.arguments)
            molecules.add(byName.get(name));
        List<String> paragraph = new ArrayList<>();
        paragraph.add("MATRIX " + query.id + " size=" + molecules.size());
        for (Prepared first : molecules) {
            StringBuilder row = new StringBuilder("row " + first.name());
            for (Prepared second : molecules)
                row.append(' ').append(ratio(similarities.get(first, second)));
            paragraph.add(row.toString());
        }
        Prepared bestFirst = molecules.getFirst(), bestSecond = molecules.get(1);
        Fraction best = ratio(similarities.get(bestFirst, bestSecond));
        for (int i = 0; i < molecules.size(); i++)
            for (int j = i + 1; j < molecules.size(); j++) {
                Fraction value = ratio(similarities.get(molecules.get(i), molecules.get(j)));
                if (value.compareTo(best) > 0) {
                    bestFirst = molecules.get(i);
                    bestSecond = molecules.get(j);
                    best = value;
                }
            }
        paragraph.add("best " + bestFirst.name() + " " + bestSecond.name() + " " + best);
        return paragraph;
    }
    static List<String> neighborsParagraph(Query query, List<Prepared> molecules,
                                           Map<String, Prepared> byName,
                                           Similarities similarities) {
        Prepared source = byName.get(query.arguments.getFirst());
        List<Neighbor> neighbors = new ArrayList<>();
        for (Prepared molecule : molecules)
            if (molecule != source)
                neighbors.add(new Neighbor(molecule, similarities.get(source, molecule)));
        neighbors.sort((a, b) -> {
            int c = ratio(b.value()).compareTo(ratio(a.value()));
            return c != 0
                ? c
                : Integer.compare(a.molecule().molecule.order, b.molecule().molecule.order);
        });
        List<Neighbor> result = new ArrayList<>();
        String heading;
        if (query.kind.equals("NEAREST")) {
            result.addAll(neighbors.subList(0, Math.min(query.count, neighbors.size())));
            heading = "NEAREST " + query.id + " " + source.name() + " count=" + result.size();
        } else {
            for (Neighbor neighbor : neighbors)
                if (ratio(neighbor.value()).compareTo(query.threshold) >= 0)
                    result.add(neighbor);
            heading = "WITHIN " + query.id + " " + source.name() + " threshold=" + query.threshold +
                      " count=" + result.size();
        }
        List<String> paragraph = new ArrayList<>();
        paragraph.add(heading);
        for (int i = 0; i < result.size(); i++) {
            Neighbor neighbor = result.get(i);
            paragraph.add((i + 1) + " " + neighbor.molecule().name() + " " +
                          ratio(neighbor.value()) + " common=" + neighbor.value().common());
        }
        return paragraph;
    }
    static List<String> compareParagraph(Query query, Map<String, Prepared> byName,
                                         Similarities similarities) {
        Prepared first = byName.get(query.arguments.getFirst()),
                 second = byName.get(query.arguments.get(1));
        Search.Similarity value = similarities.get(first, second);
        return List.of("COMPARE " + query.id + " " + first.name() + " " + second.name() +
                       " bits=" + first.bits.cardinality() + "," + second.bits.cardinality() +
                       " common=" + value.common() + " union=" + value.union() +
                       " tanimoto=" + ratio(value) +
                       " identical=" + (first.canonical.equals(second.canonical) ? "yes" : "no"));
    }
    static List<String> clusterParagraph(Query query, List<Prepared> molecules,
                                         Similarities similarities) {
        List<List<Integer>> neighbors = new ArrayList<>();
        for (Prepared first : molecules) {
            List<Integer> near = new ArrayList<>();
            for (Prepared second : molecules)
                if (first != second &&
                    ratio(similarities.get(first, second)).compareTo(query.threshold) >= 0)
                    near.add(second.molecule.order);
            neighbors.add(near);
        }
        List<Integer> order = new ArrayList<>();
        for (int i = 0; i < molecules.size(); i++)
            order.add(i);
        order.sort(Comparator.comparingInt((Integer i) -> - neighbors.get(i).size())
                       .thenComparingInt(Integer::intValue));
        Set<Integer> assigned = new HashSet<>();
        List<List<Integer>> clusters = new ArrayList<>();
        for (int center : order)
            if (!assigned.contains(center)) {
                List<Integer> members = new ArrayList<>();
                members.add(center);
                for (int neighbor : neighbors.get(center))
                    if (!assigned.contains(neighbor))
                        members.add(neighbor);
                clusters.add(members);
                assigned.addAll(members);
            }
        int singletons = 0;
        for (List<Integer> members : clusters)
            if (members.size() == 1)
                singletons++;
        List<String> paragraph = new ArrayList<>();
        paragraph.add("CLUSTER " + query.id + " threshold=" + query.threshold +
                      " clusters=" + clusters.size() + " singletons=" + singletons);
        int number = 0;
        for (List<Integer> members : clusters) {
            if (members.size() == 1)
                continue;
            number++;
            List<Prepared> selected = new ArrayList<>();
            for (int member : members)
                selected.add(molecules.get(member));
            paragraph.add("cluster " + number + " centroid=" + selected.getFirst().name() +
                          " size=" + selected.size() + " members=" + memberNames(selected));
        }
        return paragraph;
    }
    static List<List<String>> similarityParagraphs(List<Query> queries, List<Prepared> molecules,
                                                   Map<String, Prepared> byName) {
        List<String> fingerprints = new ArrayList<>();
        fingerprints.add("FINGERPRINTS molecules=" + molecules.size() + " size=1024 depth=5");
        for (Prepared molecule : molecules)
            fingerprints.add(molecule.name() + " bits=" + molecule.bits.cardinality() +
                             " paths=" + molecule.paths);
        List<List<String>> paragraphs = new ArrayList<>();
        paragraphs.add(fingerprints);
        Similarities similarities = new Similarities();
        for (Query query : queries) {
            List<String> paragraph = switch (query.kind) {
                case "MATRIX" -> matrixParagraph(query, byName, similarities);
                case "NEAREST", "WITHIN" ->
                    neighborsParagraph(query, molecules, byName, similarities);
                case "COMPARE" -> compareParagraph(query, byName, similarities);
                case "CLUSTER" -> clusterParagraph(query, molecules, similarities);
                default -> null;
            };
            if (paragraph != null)
                paragraphs.add(paragraph);
        }
        return paragraphs;
    }
    static List<String> causesParagraph(Map<String, Integer> causes) {
        List<Map.Entry<String, Integer>> ordered = new ArrayList<>(causes.entrySet());
        ordered.sort(
            Comparator.comparingInt((Map.Entry<String, Integer> entry) -> - entry.getValue())
                .thenComparing(Map.Entry::getKey));
        List<String> paragraph = new ArrayList<>();
        paragraph.add("CAUSES kinds=" + causes.size());
        for (var entry : ordered)
            paragraph.add(entry.getKey() + "=" + entry.getValue());
        return paragraph;
    }
    static String paragraphsText(List<List<String>> paragraphs) {
        List<String> blocks = new ArrayList<>();
        for (List<String> paragraph : paragraphs)
            blocks.add(String.join("\n", paragraph));
        return String.join("\n\n", blocks) + "\n";
    }
    public static void main(String[] args) throws Exception {
        Map<String, Molecule.Element> elements = Molecule.readElements();
        Map<String, Integer> causes = new HashMap<>();
        ReadMolecules read = readMolecules(elements, causes);
        List<Prepared> molecules = read.molecules();
        Map<String, Prepared> byName = new HashMap<>();
        for (Prepared molecule : molecules)
            byName.put(molecule.name(), molecule);
        ReadQueries queryRead = readQueries(elements, byName, causes);
        List<Query> queries = queryRead.queries();
        Map<String, String> outputs = new LinkedHashMap<>();
        outputs.put("properties.csv", String.join("\n", propertiesLines(molecules)) + "\n");
        outputs.put("canonical.txt", paragraphsText(canonicalParagraphs(molecules)));
        outputs.put("rings.txt", paragraphsText(ringParagraphs(molecules)));
        outputs.put("substructure.txt",
                    paragraphsText(substructureParagraphs(queries, molecules, byName)));
        outputs.put("similarity.txt",
                    paragraphsText(similarityParagraphs(queries, molecules, byName)));
        outputs.put("errors.txt", paragraphsText(List.of(read.errors(), queryRead.errors(),
                                                         causesParagraph(causes))));
        Files.createDirectories(Path.of("output"));
        for (var entry : outputs.entrySet())
            Files.writeString(Path.of("output", entry.getKey()), entry.getValue(),
                              StandardCharsets.US_ASCII);
    }
}

import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
final class Molecule {
    record Element(String symbol, int number, int weight, List<Integer> valences) {}
    record Edge(int first, int second) implements Comparable<Edge> {
        Edge {
            if (first > second) {
                int temporary = first;
                first = second;
                second = temporary;
            }
        }
        public int compareTo(Edge other) {
            int c = Integer.compare(first, other.first);
            return c != 0 ? c : Integer.compare(second, other.second);
        }
    }
    static final Set<String> ORGANIC = Set.of("B", "C", "N", "O", "P", "S", "F", "Cl", "Br", "I"),
                             AROMATIC = Set.of("B", "C", "N", "O", "P", "S");
    static int bondType(char symbol) {
        return switch (symbol) {
            case '-', '/', '\\' -> 1;
            case '=' -> 2;
            case '#' -> 3;
            case ':' -> 4;
            default -> 5;
        };
    }
    static final class AnalysisError extends RuntimeException {
        String reason;
        int column;
        AnalysisError(String reason, int column) {
            super(reason);
            this.reason = reason;
            this.column = column;
        }
    }
    static final class Atom {
        Element element;
        boolean aromatic, bracket;
        int mass, charge, hydrogens, column;
        Search.AtomMatch matcher;
        Atom(Element element, boolean aromatic, int mass, int charge, int hydrogens,
             boolean bracket, int column) {
            this.element = element;
            this.aromatic = aromatic;
            this.mass = mass;
            this.charge = charge;
            this.hydrogens = hydrogens;
            this.bracket = bracket;
            this.column = column;
        }
    }
    static final class Bond {
        Edge ends;
        Character symbol;
        Integer expected;
        int kind, multiplicity;
        boolean ring;
        Bond(int first, int second, Character symbol) {
            ends = new Edge(first, second);
            this.symbol = symbol;
        }
    }
    Map<String, Element> elements;
    List<Atom> atoms = new ArrayList<>();
    List<Map<Integer, Bond>> neighbors = new ArrayList<>();
    Map<Edge, Bond> bonds = new TreeMap<>();
    List<List<Integer>> rings = new ArrayList<>();
    Set<Integer> ringAtoms = new TreeSet<>();
    String name;
    int order;
    Molecule(Map<String, Element> elements) { this.elements = elements; }
    int addAtom(Atom atom) {
        int number = atoms.size();
        atoms.add(atom);
        neighbors.add(new TreeMap<>());
        return number;
    }
    Bond addBond(int first, int second, Character symbol) {
        Bond bond = new Bond(first, second, symbol);
        bonds.put(bond.ends, bond);
        neighbors.get(first).put(second, bond);
        neighbors.get(second).put(first, bond);
        return bond;
    }
    int degree(int number) { return neighbors.get(number).size(); }
    int baseTotal(int number) {
        int total = 0;
        for (Bond bond : neighbors.get(number).values())
            total += bond.kind == 4 ? 1 : bond.kind;
        return total;
    }
    int bondTotal(int number) {
        int total = 0;
        for (Bond bond : neighbors.get(number).values())
            total += bond.multiplicity;
        return total;
    }
    boolean needsPi(int number, int hydrogens) {
        Atom atom = atoms.get(number);
        return atom.aromatic &&
            atom.element.valences().getFirst() + atom.charge >= baseTotal(number) + hydrogens + 1;
    }
    static Integer organicHydrogens(Atom atom, int total) {
        for (int valence : atom.element.valences())
            if (valence >= total)
                return valence - total;
        return null;
    }
    static Map<String, Element> readElements() throws Exception {
        Map<String, Element> elements = new HashMap<>();
        for (String line :
             Files.readAllLines(Path.of("input/elements.txt"), StandardCharsets.US_ASCII)) {
            if (line.isEmpty() || line.startsWith("#"))
                continue;
            String[] f = line.split(" ");
            List<Integer> valences = new ArrayList<>();
            for (String value : f[3].split(","))
                valences.add(Integer.parseInt(value));
            elements.put(f[0], new Element(f[0], Integer.parseInt(f[1]), Integer.parseInt(f[2]),
                                           List.copyOf(valences)));
        }
        return elements;
    }
}

import java.util.*;
final class RingsAromatic {
    record Candidate(List<Integer> sequence, BitSet bonds) {}
    static Set<Molecule.Edge> ringEdges(List<Integer> sequence) {
        Set<Molecule.Edge> edges = new TreeSet<>();
        for (int i = 0; i < sequence.size(); i++)
            edges.add(new Molecule.Edge(sequence.get((i + sequence.size() - 1) % sequence.size()),
                                        sequence.get(i)));
        return edges;
    }
    static int compareSequence(List<Integer> a, List<Integer> b) {
        for (int i = 0; i < Math.min(a.size(), b.size()); i++) {
            int c = Integer.compare(a.get(i), b.get(i));
            if (c != 0)
                return c;
        }
        return Integer.compare(a.size(), b.size());
    }
    static List<Integer> ringSequence(List<Integer> sequence) {
        int first = sequence.indexOf(Collections.min(sequence));
        List<Integer> forward = new ArrayList<>();
        for (int i = 0; i < sequence.size(); i++)
            forward.add(sequence.get((first + i) % sequence.size()));
        List<Integer> backward = new ArrayList<>();
        backward.add(forward.getFirst());
        for (int i = forward.size() - 1; i > 0; i--)
            backward.add(forward.get(i));
        return compareSequence(forward, backward) <= 0 ? forward : backward;
    }
    static void findRings(Molecule molecule) {
        List<Molecule.Edge> bonds = new ArrayList<>(molecule.bonds.keySet());
        Map<Molecule.Edge, Integer> indices = new HashMap<>();
        for (int i = 0; i < bonds.size(); i++)
            indices.put(bonds.get(i), i);
        List<Candidate> candidates = new ArrayList<>();
        Set<BitSet> seen = new HashSet<>();
        int count = molecule.atoms.size();
        for (int root = 0; root < count; root++) {
            int[] parents = new int[count];
            Arrays.fill(parents, -2);
            parents[root] = -1;
            Deque<Integer> queue = new ArrayDeque<>();
            queue.add(root);
            while (!queue.isEmpty()) {
                int atom = queue.remove();
                for (int neighbor : molecule.neighbors.get(atom).keySet())
                    if (parents[neighbor] == -2) {
                        parents[neighbor] = atom;
                        queue.add(neighbor);
                    }
            }
            List<List<Integer>> paths = new ArrayList<>();
            for (int atom = 0; atom < count; atom++) {
                List<Integer> path = new ArrayList<>();
                for (int current = atom; current != -1; current = parents[current])
                    path.add(current);
                paths.add(path);
            }
            for (Molecule.Edge edge : bonds) {
                int first = edge.first(), second = edge.second();
                if (parents[first] == second || parents[second] == first)
                    continue;
                Set<Integer> shared = new HashSet<>(paths.get(first));
                shared.retainAll(paths.get(second));
                if (shared.size() != 1 || !shared.contains(root))
                    continue;
                List<Integer> sequence = new ArrayList<>(paths.get(first));
                Collections.reverse(sequence);
                sequence.addAll(paths.get(second).subList(0, paths.get(second).size() - 1));
                BitSet bits = new BitSet();
                for (Molecule.Edge ringEdge : ringEdges(sequence))
                    bits.set(indices.get(ringEdge));
                if (seen.add(bits))
                    candidates.add(new Candidate(sequence, bits));
            }
        }
        candidates.sort(Comparator.comparingInt(candidate -> candidate.sequence().size()));
        Map<Integer, BitSet> basis = new HashMap<>();
        for (Candidate candidate : candidates) {
            BitSet reduced = (BitSet)candidate.bonds().clone();
            while (!reduced.isEmpty()) {
                int pivot = reduced.length() - 1;
                BitSet vector = basis.get(pivot);
                if (vector == null) {
                    basis.put(pivot, reduced);
                    molecule.rings.add(ringSequence(candidate.sequence()));
                    break;
                }
                reduced.xor(vector);
            }
        }
        molecule.rings.sort(Comparator.comparingInt((List<Integer> ring) -> ring.size())
                                .thenComparing(RingsAromatic::compareSequence));
        for (List<Integer> ring : molecule.rings) {
            molecule.ringAtoms.addAll(ring);
            for (Molecule.Edge edge : ringEdges(ring))
                molecule.bonds.get(edge).ring = true;
        }
    }
    static List<Set<Integer>> aromaticSystems(Molecule molecule, Set<Integer> needing) {
        Set<Integer> remaining = new TreeSet<>(needing);
        List<Set<Integer>> systems = new ArrayList<>();
        while (!remaining.isEmpty()) {
            int start = Collections.min(remaining);
            remaining.remove(start);
            Set<Integer> system = new TreeSet<>();
            system.add(start);
            Deque<Integer> queue = new ArrayDeque<>();
            queue.add(start);
            while (!queue.isEmpty()) {
                int atom = queue.remove();
                for (var entry : molecule.neighbors.get(atom).entrySet())
                    if (entry.getValue().kind == 4 && remaining.remove(entry.getKey())) {
                        system.add(entry.getKey());
                        queue.add(entry.getKey());
                    }
            }
            systems.add(system);
        }
        return systems;
    }
    static boolean match(Molecule molecule, Set<Integer> unpaired, Set<Molecule.Edge> pairs) {
        if (unpaired.isEmpty())
            return true;
        int first = Collections.min(unpaired);
        unpaired.remove(first);
        for (var entry : molecule.neighbors.get(first).entrySet()) {
            int second = entry.getKey();
            Molecule.Bond bond = entry.getValue();
            if (!unpaired.contains(second) || bond.kind != 4)
                continue;
            unpaired.remove(second);
            pairs.add(bond.ends);
            if (match(molecule, unpaired, pairs))
                return true;
            pairs.remove(bond.ends);
            unpaired.add(second);
        }
        unpaired.add(first);
        return false;
    }
    static void kekulize(Molecule molecule, Set<Integer> needing) {
        Set<Molecule.Edge> selected = new HashSet<>();
        for (Set<Integer> system : aromaticSystems(molecule, needing)) {
            Set<Molecule.Edge> pairs = new HashSet<>();
            if (!match(molecule, new TreeSet<>(system), pairs))
                throw new Molecule.AnalysisError(
                    "kekulization failed", molecule.atoms.get(Collections.min(system)).column);
            selected.addAll(pairs);
        }
        for (Molecule.Bond bond : molecule.bonds.values())
            bond.multiplicity = bond.kind == 4 ? (selected.contains(bond.ends) ? 2 : 1) : bond.kind;
    }
}

import java.util.*;
final class Search {
    record Choice(String symbol, boolean aromatic) {}
    record AtomMatch(Set<Choice> choices, Boolean aromatic) {
        boolean matches(Molecule.Atom atom) {
            return choices != null
                ? choices.contains(new Choice(atom.element.symbol(), atom.aromatic))
                : aromatic == null || aromatic == atom.aromatic;
        }
    }
    static SmilesParser.AtomRead patternAtom(String text, int position) {
        char c = text.charAt(position);
        AtomMatch match;
        int end;
        if (c == '*' || c == 'A' || c == 'a') {
            match = new AtomMatch(null, c == '*' ? null : c == 'a');
            end = position + 1;
        } else if (c == '[') {
            end = text.indexOf(']', position + 1);
            if (end < 0)
                throw new Molecule.AnalysisError("unclosed bracket", position + 1);
            Set<Choice> choices = new HashSet<>();
            for (String item : text.substring(position + 1, end).split(",", -1)) {
                SmilesParser.Organic organic = SmilesParser.organic(item, 0);
                if (organic == null || organic.end() != item.length())
                    throw new Molecule.AnalysisError("bad bracket atom", position + 1);
                choices.add(new Choice(organic.symbol(), organic.aromatic()));
            }
            match = new AtomMatch(choices, null);
            end++;
        } else {
            SmilesParser.Organic organic = SmilesParser.organic(text, position);
            if (organic == null)
                throw new Molecule.AnalysisError("unexpected character", position + 1);
            match = new AtomMatch(Set.of(new Choice(organic.symbol(), organic.aromatic())), null);
            end = organic.end();
        }
        Molecule.Atom atom = new Molecule.Atom(null, false, 0, 0, 0, false, position + 1);
        atom.matcher = match;
        return new SmilesParser.AtomRead(atom, end);
    }
    static Molecule moleculePattern(Molecule molecule) {
        Molecule pattern = new Molecule(molecule.elements);
        for (Molecule.Atom original : molecule.atoms) {
            Molecule.Atom atom = new Molecule.Atom(null, false, 0, 0, 0, false, 0);
            atom.matcher = new AtomMatch(
                Set.of(new Choice(original.element.symbol(), original.aromatic)), null);
            pattern.addAtom(atom);
        }
        for (Molecule.Bond original : molecule.bonds.values()) {
            Molecule.Bond bond =
                pattern.addBond(original.ends.first(), original.ends.second(), null);
            bond.expected = original.kind;
        }
        return pattern;
    }
    static boolean bondMatches(Molecule.Bond pattern, Molecule.Bond molecule) {
        if (pattern.expected != null)
            return pattern.expected == molecule.kind;
        if (pattern.symbol == null)
            return molecule.kind == 1 || molecule.kind == 4;
        if (pattern.symbol == '~')
            return true;
        return Molecule.bondType(pattern.symbol) == molecule.kind;
    }
    record Embeddings(int count, int unique, List<Integer> mapping) {}
    static final class Matching {
        Molecule pattern, molecule;
        List<List<Integer>> candidates = new ArrayList<>();
        int[] mapping;
        BitSet used = new BitSet();
        Set<BitSet> unique = new HashSet<>();
        int count;
        List<Integer> first;
        Matching(Molecule pattern, Molecule molecule) {
            this.pattern = pattern;
            this.molecule = molecule;
            mapping = new int[pattern.atoms.size()];
            for (int i = 0; i < pattern.atoms.size(); i++) {
                List<Integer> atoms = new ArrayList<>();
                for (int number = 0; number < molecule.atoms.size(); number++)
                    if (pattern.atoms.get(i).matcher.matches(molecule.atoms.get(number)) &&
                        molecule.degree(number) >= pattern.degree(i))
                        atoms.add(number);
                candidates.add(atoms);
            }
        }
        void assign(int index) {
            if (index == mapping.length) {
                count++;
                unique.add((BitSet)used.clone());
                if (first == null) {
                    first = new ArrayList<>();
                    for (int number : mapping)
                        first.add(number);
                }
                return;
            }
            for (int atom : candidates.get(index)) {
                if (used.get(atom))
                    continue;
                boolean allowed = true;
                for (var entry : pattern.neighbors.get(index).entrySet())
                    if (entry.getKey() < index) {
                        Molecule.Bond target =
                            molecule.neighbors.get(atom).get(mapping[entry.getKey()]);
                        if (target == null || !bondMatches(entry.getValue(), target)) {
                            allowed = false;
                            break;
                        }
                    }
                if (!allowed)
                    continue;
                mapping[index] = atom;
                used.set(atom);
                assign(index + 1);
                used.clear(atom);
            }
        }
    }
    static Embeddings embeddings(Molecule pattern, Molecule molecule) {
        if (pattern.atoms.size() > molecule.atoms.size())
            return new Embeddings(0, 0, null);
        Matching matching = new Matching(pattern, molecule);
        matching.assign(0);
        return new Embeddings(matching.count, matching.unique.size(), matching.first);
    }
    record Fingerprint(BitSet bits, int paths) {}
    record Similarity(int common, int union) {}
    static final class Paths {
        Molecule molecule;
        int[] codes;
        BitSet used = new BitSet(), bits = new BitSet(1024);
        int count;
        Paths(Molecule molecule) {
            this.molecule = molecule;
            codes = new int[molecule.atoms.size()];
            for (int i = 0; i < codes.length; i++) {
                Molecule.Atom atom = molecule.atoms.get(i);
                codes[i] =
                    16 * atom.element.number() + (atom.aromatic ? 8 : 0) + molecule.degree(i);
            }
        }
        void extend(int atom, int depth, int value) {
            count++;
            bits.set(value % 1024);
            if (depth == 5)
                return;
            for (var entry : molecule.neighbors.get(atom).entrySet()) {
                int neighbor = entry.getKey();
                if (used.get(neighbor))
                    continue;
                int next = (value * 31 + entry.getValue().kind) % 1000003;
                next = (next * 31 + codes[neighbor]) % 1000003;
                used.set(neighbor);
                extend(neighbor, depth + 1, next);
                used.clear(neighbor);
            }
        }
    }
    static Fingerprint fingerprint(Molecule molecule) {
        Paths paths = new Paths(molecule);
        for (int atom = 0; atom < molecule.atoms.size(); atom++) {
            paths.used.set(atom);
            paths.extend(atom, 0, paths.codes[atom]);
            paths.used.clear(atom);
        }
        return new Fingerprint(paths.bits, paths.count);
    }
    static Similarity tanimoto(BitSet first, BitSet second) {
        BitSet common = (BitSet)first.clone();
        common.and(second);
        int count = common.cardinality();
        return new Similarity(count, first.cardinality() + second.cardinality() - count);
    }
}

import java.util.*;
final class SmilesParser {
    record Organic(String symbol, boolean aromatic, int end) {}
    record AtomRead(Molecule.Atom atom, int end) {}
    record Pending(char symbol, int column) {}
    record Branch(int atom, int column) {}
    record OpenRing(int atom, Character symbol, int column) {}
    static boolean digit(char c) { return c >= '0' && c <= '9'; }
    static Organic organic(String text, int position) {
        if (position >= text.length())
            return null;
        String pair = text.substring(position, Math.min(position + 2, text.length()));
        if (pair.equals("Cl") || pair.equals("Br"))
            return new Organic(pair, false, position + 2);
        char c = text.charAt(position);
        if ("BCNOPSFI".indexOf(c) >= 0)
            return new Organic(Character.toString(c), false, position + 1);
        if ("bcnops".indexOf(c) >= 0)
            return new Organic(Character.toString(Character.toUpperCase(c)), true, position + 1);
        return null;
    }
    static Molecule.Atom bracket(String content, Map<String, Molecule.Element> elements,
                                 int column) {
        int p = 0;
        while (p < content.length() && digit(content.charAt(p)))
            p++;
        if (p >= 4 || p > 0 && content.charAt(0) == '0')
            throw new Molecule.AnalysisError("bad bracket atom", column);
        int mass = p == 0 ? 0 : Integer.parseInt(content.substring(0, p));
        if (p == content.length())
            throw new Molecule.AnalysisError("bad bracket atom", column);
        char c = content.charAt(p);
        String symbol;
        boolean aromatic;
        if ("bcnops".indexOf(c) >= 0) {
            symbol = Character.toString(Character.toUpperCase(c));
            aromatic = true;
            p++;
        } else if (c >= 'A' && c <= 'Z') {
            String pair = content.substring(p, Math.min(p + 2, content.length()));
            if (pair.length() == 2 && pair.charAt(1) >= 'a' && pair.charAt(1) <= 'z' &&
                elements.containsKey(pair)) {
                symbol = pair;
                p += 2;
            } else if (elements.containsKey(Character.toString(c))) {
                symbol = Character.toString(c);
                p++;
            } else
                throw new Molecule.AnalysisError("unknown element", column);
            aromatic = false;
        } else
            throw new Molecule.AnalysisError("bad bracket atom", column);
        if (content.startsWith("@@", p))
            p += 2;
        else if (content.startsWith("@", p))
            p++;
        int hydrogens = 0;
        if (p < content.length() && content.charAt(p) == 'H') {
            hydrogens = 1;
            p++;
            if (p < content.length() && digit(content.charAt(p)))
                hydrogens = content.charAt(p++) - '0';
        }
        int charge = 0;
        if (p < content.length() && (content.charAt(p) == '+' || content.charAt(p) == '-')) {
            charge = content.charAt(p++) == '+' ? 1 : -1;
            if (p < content.length() && content.charAt(p) >= '1' && content.charAt(p) <= '9')
                charge *= content.charAt(p++) - '0';
        }
        if (p != content.length())
            throw new Molecule.AnalysisError("bad bracket atom", column);
        return new Molecule.Atom(elements.get(symbol), aromatic, mass, charge, hydrogens, true,
                                 column);
    }
    static AtomRead atom(String text, int position, Map<String, Molecule.Element> elements) {
        if (text.charAt(position) == '[') {
            int end = text.indexOf(']', position + 1);
            if (end < 0)
                throw new Molecule.AnalysisError("unclosed bracket", position + 1);
            return new AtomRead(bracket(text.substring(position + 1, end), elements, position + 1),
                                end + 1);
        }
        Organic organic = organic(text, position);
        if (organic == null)
            throw new Molecule.AnalysisError("unexpected character", position + 1);
        return new AtomRead(new Molecule.Atom(elements.get(organic.symbol()), organic.aromatic(), 0,
                                              0, 0, false, position + 1),
                            organic.end());
    }
    static Molecule parse(String text, Map<String, Molecule.Element> elements, boolean pattern) {
        Molecule molecule = new Molecule(elements);
        String symbols = pattern ? "-=#:~" : "-/\\=#:";
        Integer current = null;
        Pending pending = null;
        List<Branch> branches = new ArrayList<>();
        Map<Integer, OpenRing> openRings = new HashMap<>();
        int position = 0;
        while (position < text.length()) {
            char c = text.charAt(position);
            int column = position + 1;
            if (symbols.indexOf(c) >= 0) {
                if (current == null || pending != null)
                    throw new Molecule.AnalysisError("misplaced bond", column);
                pending = new Pending(c, column);
                position++;
            } else if (c == '(') {
                if (current == null || pending != null || text.charAt(position - 1) == '(')
                    throw new Molecule.AnalysisError("misplaced branch", column);
                branches.add(new Branch(current, column));
                position++;
            } else if (c == ')') {
                if (branches.isEmpty())
                    throw new Molecule.AnalysisError("unmatched parenthesis", column);
                if (pending != null)
                    throw new Molecule.AnalysisError("dangling bond", pending.column());
                if (text.charAt(position - 1) == '(')
                    throw new Molecule.AnalysisError("empty branch", column);
                current = branches.removeLast().atom();
                position++;
            } else if (digit(c) || c == '%') {
                if (current == null)
                    throw new Molecule.AnalysisError("misplaced ring closure", column);
                int ring;
                if (c == '%') {
                    if (position + 2 >= text.length() || !digit(text.charAt(position + 1)) ||
                        !digit(text.charAt(position + 2)))
                        throw new Molecule.AnalysisError("bad ring number", column);
                    ring = Integer.parseInt(text.substring(position + 1, position + 3));
                    position += 3;
                } else {
                    ring = c - '0';
                    position++;
                }
                Character symbol = pending == null ? null : pending.symbol();
                pending = null;
                OpenRing opening = openRings.get(ring);
                if (opening == null) {
                    openRings.put(ring, new OpenRing(current, symbol, column));
                    continue;
                }
                if (opening.atom() == current)
                    throw new Molecule.AnalysisError("self bond", column);
                if (opening.symbol() != null && symbol != null &&
                    Molecule.bondType(opening.symbol()) != Molecule.bondType(symbol))
                    throw new Molecule.AnalysisError("ring bond mismatch", column);
                if (molecule.neighbors.get(opening.atom()).containsKey(current))
                    throw new Molecule.AnalysisError("duplicate bond", column);
                molecule.addBond(opening.atom(), current,
                                 symbol == null ? opening.symbol() : symbol);
                openRings.remove(ring);
            } else {
                AtomRead read =
                    pattern ? Search.patternAtom(text, position) : atom(text, position, elements);
                position = read.end();
                int next = molecule.addAtom(read.atom());
                if (current != null)
                    molecule.addBond(current, next, pending == null ? null : pending.symbol());
                current = next;
                pending = null;
            }
        }
        if (pending != null)
            throw new Molecule.AnalysisError("dangling bond", pending.column());
        if (!branches.isEmpty())
            throw new Molecule.AnalysisError("unmatched parenthesis", branches.getFirst().column());
        if (!openRings.isEmpty())
            throw new Molecule.AnalysisError(
                "unclosed ring",
                openRings.values().stream().mapToInt(OpenRing::column).min().orElseThrow());
        return molecule;
    }
}
